#!/usr/bin/env bash
#
# Emit the experiment credentials as `export` lines, read live from the cluster.
#
# WHY: none of these values should ever be typed into .env by hand, and none of them should
# be committed. They all already exist in the cluster:
#   - KEYCLOAK_CLIENT_SECRET  -> generated by Keycloak for the `atlas-loadtest` client
#   - LOADTEST_USER_PASSWORD  -> secret/atlas-realm-credentials, key `loadtest-password`
#   - KEYCLOAK_ADMIN_PASSWORD -> secret/keycloak-initial-admin (the bootstrap admin)
# This script fetches them, so .env only ever holds non-secret knobs.
#
# Usage — evaluate it into the current shell (note the leading `eval`):
#   export LB=<ingress EXTERNAL-IP>
#   eval "$(./scripts/cluster-credentials.sh)"
#   set -a; source .env; set +a          # non-secret knobs, if you keep a .env
#   make run EXP=01-high-booking-concurrency
#
# Print without evaluating, to see what it would set:
#   ./scripts/cluster-credentials.sh
#
# Config (all env-overridable):
#   LB                      ingress LoadBalancer IP    (required unless KEYCLOAK_URL is set)
#   KEYCLOAK_URL            Keycloak base URL          (default http://keycloak.$LB.nip.io)
#   ATLAS_GATEWAY           API edge                   (default http://$LB)
#   KEYCLOAK_REALM          realm                      (default atlas)
#   KEYCLOAK_CLIENT_ID      confidential client        (default atlas-loadtest)
#   KEYCLOAK_ADMIN_REALM    admin realm                (default master)
#   KEYCLOAK_ADMIN_USER     admin username             (default from keycloak-initial-admin)
#   KEYCLOAK_ADMIN_PASSWORD admin password             (default from keycloak-initial-admin)
#   NS_SYSTEM               Keycloak namespace         (default atlas-system)
#
# NOTE: Runbook Step 5a tells you to delete `temp-admin` once a permanent admin exists.
# After that, export KEYCLOAK_ADMIN_USER / KEYCLOAK_ADMIN_PASSWORD before running this.
set -euo pipefail

NS_SYSTEM="${NS_SYSTEM:-atlas-system}"
REALM="${KEYCLOAK_REALM:-atlas}"
CLIENT_ID="${KEYCLOAK_CLIENT_ID:-atlas-loadtest}"
ADMIN_REALM="${KEYCLOAK_ADMIN_REALM:-master}"
ADMIN_CLIENT="${KEYCLOAK_ADMIN_CLIENT:-admin-cli}"
CREDENTIALS_SECRET="${CREDENTIALS_SECRET:-atlas-realm-credentials}"

die() { printf 'error: %s\n' "$*" >&2; exit 1; }
for dep in kubectl curl jq; do
  command -v "$dep" >/dev/null 2>&1 || die "missing dependency: $dep"
done

if [[ -z "${KEYCLOAK_URL:-}" ]]; then
  [[ -n "${LB:-}" ]] || die "set LB to the ingress EXTERNAL-IP, or set KEYCLOAK_URL directly"
  KEYCLOAK_URL="http://keycloak.${LB}.nip.io"
fi
ATLAS_GATEWAY="${ATLAS_GATEWAY:-${LB:+http://$LB}}"

# ── Admin token ──────────────────────────────────────────────────────────────
ADMIN_USER="${KEYCLOAK_ADMIN_USER:-$(kubectl -n "$NS_SYSTEM" get secret keycloak-initial-admin \
  -o jsonpath='{.data.username}' 2>/dev/null | base64 -d)}"
ADMIN_PASSWORD="${KEYCLOAK_ADMIN_PASSWORD:-$(kubectl -n "$NS_SYSTEM" get secret keycloak-initial-admin \
  -o jsonpath='{.data.password}' 2>/dev/null | base64 -d)}"
[[ -n "$ADMIN_USER" && -n "$ADMIN_PASSWORD" ]] \
  || die "no admin credentials — secret/keycloak-initial-admin is gone (deleted temp-admin?). Export KEYCLOAK_ADMIN_USER and KEYCLOAK_ADMIN_PASSWORD."

# Never pipe curl straight into jq: a non-JSON body (an nginx 404/503 HTML page is the
# common one) surfaces as an opaque `jq: parse error` instead of the real problem. Capture
# the status and the body, judge the status first.
raw=$(curl -sS --connect-timeout 5 --max-time 15 -w $'\n%{http_code}' \
  "$KEYCLOAK_URL/realms/$ADMIN_REALM/protocol/openid-connect/token" \
  -d grant_type=password -d "client_id=$ADMIN_CLIENT" \
  --data-urlencode "username=$ADMIN_USER" --data-urlencode "password=$ADMIN_PASSWORD") \
  || die "could not reach $KEYCLOAK_URL in time — is the Keycloak Ingress up and the host resolvable? On Civo, keycloak.<lb-hostname>.nip.io does not resolve; use a resolved-IP URL or a port-forward. (Runbook Step 5)"
code="${raw##*$'\n'}"; body="${raw%$'\n'*}"

case "$code" in
  200) ;;
  401) die "admin login rejected. If you deleted temp-admin (Runbook 5a), export KEYCLOAK_ADMIN_USER and KEYCLOAK_ADMIN_PASSWORD for your permanent admin." ;;
  404) die "HTTP 404 from $KEYCLOAK_URL — the Keycloak Ingress is not routing (TS-PLATFORM-04)." ;;
  503) die "HTTP 503 from $KEYCLOAK_URL — Keycloak has no ready pod yet. Check: kubectl -n $NS_SYSTEM get pod keycloak-0" ;;
  *)   die "admin token request returned HTTP $code: $(printf '%.200s' "$body")" ;;
esac

TOKEN=$(jq -r '.access_token // empty' <<<"$body")
[[ -n "$TOKEN" ]] || die "no access_token in the response: $(printf '%.200s' "$body")"

# ── Client secret (generated by Keycloak at import time) ─────────────────────
CLIENT_UUID=$(curl -sS -G "$KEYCLOAK_URL/admin/realms/$REALM/clients" \
  --data-urlencode "clientId=$CLIENT_ID" \
  -H "Authorization: Bearer $TOKEN" | jq -r '.[0].id // empty')
[[ -n "$CLIENT_UUID" ]] \
  || die "client '$CLIENT_ID' not found in realm '$REALM' — did the realm import run? (Runbook 5b)"

CLIENT_SECRET=$(curl -sS "$KEYCLOAK_URL/admin/realms/$REALM/clients/$CLIENT_UUID/client-secret" \
  -H "Authorization: Bearer $TOKEN" | jq -r '.value // empty')
[[ -n "$CLIENT_SECRET" ]] \
  || die "'$CLIENT_ID' has no secret — is it configured as a public client?"

# ── Load-test pool password ──────────────────────────────────────────────────
LOADTEST_PASSWORD=$(kubectl -n "$NS_SYSTEM" get secret "$CREDENTIALS_SECRET" \
  -o jsonpath='{.data.loadtest-password}' 2>/dev/null | base64 -d)
[[ -n "$LOADTEST_PASSWORD" ]] \
  || die "secret/$CREDENTIALS_SECRET has no 'loadtest-password' key — see Runbook Step 5b"

# ── Emit ─────────────────────────────────────────────────────────────────────
# Single-quoted with embedded quotes escaped, so values with shell metacharacters survive.
emit() { printf "export %s='%s'\n" "$1" "${2//\'/\'\\\'\'}"; }

emit KEYCLOAK_URL            "$KEYCLOAK_URL"
[[ -n "$ATLAS_GATEWAY" ]] && emit ATLAS_GATEWAY "$ATLAS_GATEWAY"
emit KEYCLOAK_REALM          "$REALM"
emit KEYCLOAK_CLIENT_ID      "$CLIENT_ID"
emit KEYCLOAK_CLIENT_SECRET  "$CLIENT_SECRET"
emit LOADTEST_USER_PASSWORD  "$LOADTEST_PASSWORD"
emit KEYCLOAK_ADMIN_REALM    "$ADMIN_REALM"
emit KEYCLOAK_ADMIN_USER     "$ADMIN_USER"
emit KEYCLOAK_ADMIN_PASSWORD "$ADMIN_PASSWORD"
